// Chunk A datasets (PAGES_SPEC_EXTRA X1/X2 glossary, X5 dives, X6 authors, X7 learn, X11 research, X20 chapters).
// Content policy: every visible string is generated placeholder copy (content/lorem.js); only the slugs (from
// MISSING_ROUTES.txt) and per-element lengths / counts / block types measured on the original are stored, so
// each page wraps and stacks like its original without reusing any of its text. Glossary terms and dive titles
// are derived from the slug words (allowed). Person names are invented. Deterministic: same slug, same page.
import { rng, chars, exactTitle, shaped, hash, int, pick, slugify } from '../../content/lorem.js'
import { fromShape, titleFromSlug, nameOfLength, diveTitle } from '../../content/slugNames.js'

export { titleFromSlug, nameOfLength }

const lazy = (fn) => { let v; return () => (v ??= fn()) }
const nums = (s) => (s ? String(s).split(',').map(Number) : [])
// wordLens / shapedWords / fromShape: shared with the hub cards (content/slugNames.js).
const question = (w, seed) => { const t = fromShape(w, seed); return /[.?!]$/.test(t) ? `${t.slice(0, -1)}?` : `${t.slice(0, -1)}?` }

/* ---------------- shared text helpers ---------------- */
// titleFromSlug: shared with the hub cards (content/slugNames.js).

const MONTHS = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec']
const dateFor = (seed) => { const r = rng(seed); return `${pick(r, MONTHS)} ${int(r, 10, 28)}, ${int(r, 2024, 2026)}` }

// nameOfLength (invented names): shared with the hub bylines (content/slugNames.js).
const ROLES = ['Engineer', 'Researcher', 'Data Analyst', 'Staff Engineer', 'Data Scientist', 'Product Manager', 'Technical Writer', 'Software Engineer', 'Community Manager', 'Founding Engineer', 'Developer Advocate', 'Engineering Manager', 'Solutions Architect', 'Principal Data Engineer', 'Head of Developer Relations']
const roleOfLength = (n) => ROLES.reduce((a, b) => (Math.abs(b.length - n) < Math.abs(a.length - n) ? b : a))

/* ---------------- shape decoder -> ArticleProse block AST ---------------- */
const SQL_LINES = [
  'SELECT region, count(*) AS orders', 'FROM sample_orders', "WHERE status = 'open'", 'GROUP BY region',
  'ORDER BY orders DESC;', 'CREATE TABLE events AS', "SELECT * FROM read_csv('events_*.csv');",
  'INSERT INTO metrics SELECT * FROM staging;', 'WITH recent AS (', '  SELECT * FROM visits WHERE day > 7', ')',
  'SELECT avg(latency) FROM recent;', 'ATTACH \'warehouse\' AS wh;', 'LIMIT 10;',
]
function codeLines(n, seed) {
  const r = rng(seed)
  return Array.from({ length: n }, (_, i) => (i === 0 ? '-- ' + exactTitle(int(r, 18, 34), seed).toLowerCase() : pick(r, SQL_LINES))).join('\n')
}

// Running text of n characters with `links` inline links spread through it.
export function inline(n, seed, links = 0, hrefFor) {
  const text = chars(Math.max(n, 6), seed)
  if (!links || !hrefFor) return [text]
  const words = text.split(' ')
  const k = Math.min(links, Math.max(1, Math.floor(words.length / 5)))
  const out = []
  let at = 0
  for (let j = 0; j < k; j++) {
    const pos = Math.floor(((j + 1) * words.length) / (k + 1)) - 1
    if (pos <= at) continue
    out.push(words.slice(at, pos).join(' ') + ' ')
    const len = Math.min(3, words.length - pos)
    out.push({ t: 'a', c: words.slice(pos, pos + len).join(' ').replace(/\.$/, ''), href: hrefFor(seed * 7 + j) })
    at = pos + len
    if (at < words.length) out.push(' ')
  }
  if (at < words.length) out.push(words.slice(at).join(' '))
  else out.push('.')
  return out
}

function listItems(spec, seed, hrefFor) {
  return spec.split(',').map((it, i) => {
    const [head, sub] = it.split('>')
    return {
      inl: inline(Number(head), seed + i * 13, 0, hrefFor),
      sub: sub ? { type: 'ul', items: sub.split('/').map((x, j) => ({ inl: inline(Number(x), seed + i * 13 + j + 400), sub: null })) } : null,
    }
  })
}

// ctx: { seed, hrefFor(seed) -> href, imgRatio, numbered: chapter number | null }
export function decodeShape(shape, ctx) {
  if (!shape) return []
  const used = new Set()
  const blocks = []
  let s = ctx.seed * 1000
  let h2 = 0
  let h3 = 0
  const heading = (type, n) => {
    let prefix = ''
    if (ctx.numbered && n > 12) {
      if (type === 'h2') { h2++; h3 = 0; prefix = `${ctx.numbered}.${h2} ` }
      else if (type === 'h3' && h2) { h3++; prefix = `${ctx.numbered}.${h2}.${h3} ` }
    }
    const text = prefix + exactTitle(Math.max(n - prefix.length, 3), ++s)
    let id = slugify(text) || `section-${s}`
    while (used.has(id)) id += '-x'
    used.add(id)
    return { type, text, id }
  }
  for (const tok of shape.split('|')) {
    const [t, ...rest] = tok.split('.')
    const arg = rest.join('.')
    if (/^h[1-6]$/.test(t)) blocks.push(heading(t === 'h1' ? 'h2' : t, Number(arg)))
    else if (t === 'p') { const [n, k] = arg.split('.').map(Number); blocks.push({ type: 'p', inl: inline(n, ++s, k || 0, ctx.hrefFor) }) }
    else if (t === 'ul' || t === 'ol' || t === 'olL') blocks.push({ type: t.slice(0, 2), items: listItems(arg, ++s * 3, ctx.hrefFor) })
    // loose bullet list (items wrapped in <p>, 24px apart on the original): one single-item list per item
    else if (t === 'ulL') listItems(arg, ++s * 3, ctx.hrefFor).forEach((it) => blocks.push({ type: 'ul', items: [it] }))
    else if (t === 'code') blocks.push({ type: 'code', lang: 'sql', code: codeLines(Number(arg) || 3, ++s) })
    else if (t === 'table') {
      // table.CxR[:cellChars...] (head cells first, then body cells row by row)
      const [dims, cellSpec] = arg.split(':')
      const [c, rws] = dims.split('x').map(Number)
      const r = rng(++s)
      const lens = nums(cellSpec)
      const cell = (k, fb) => {
        const n = lens.length ? lens[k] ?? 0 : fb
        if (!n) return ''
        return n <= 24 ? exactTitle(n, s + k) : chars(n, s + k).replace(/\.$/, '')
      }
      blocks.push({
        type: 'table',
        head: Array.from({ length: c }, (_, i) => cell(i, int(r, 5, 12)) || exactTitle(4, s + i)),
        rows: Array.from({ length: rws }, (_, j) => Array.from({ length: c }, (_, i) => cell(c + j * c + i, i === 0 ? int(r, 6, 16) : int(r, 8, 40)))),
      })
    } else if (t === 'admon') {
      const [tl, body] = arg.split(':')
      const title = tl > 8 ? exactTitle(Number(tl) - 6, ++s) : ''
      blocks.push({ type: 'admon', kind: 'info', title, children: nums(body).map((n) => ({ type: 'p', inl: inline(n, ++s, 1, ctx.hrefFor) })) })
    } else if (t === 'quote') nums(arg).forEach((n) => blocks.push({ type: 'quote', inl: inline(n, ++s) }))
    // Images scale with the column on the original: height = column width x aspect (100cqw needs the page to set
    // container-type: inline-size on the prose wrapper, class .xc-cq). img.<permille> = measured aspect h/w.
    else if (t === 'img') blocks.push({ type: 'img', h: `calc(100cqw * ${arg ? Number(arg) / 1000 : ctx.imgRatio || 0.5625})` })
    else if (t === 'cap') blocks.push({ type: 'p', inl: [{ t: 'em', c: chars(Number(arg), ++s) }] })
    else if (t === 'iframe') blocks.push({ type: 'iframe', kind: 'youtube' })
    else if (t === 'hr') blocks.push({ type: 'hr' })
  }
  return blocks
}

const faqsOf = (q, a, seed) => (q ? String(q).split(',') : []).map((w, k) => ({
  q: question(w, seed * 10 + k),
  a: chars(nums(a)[k] || 240, seed * 10 + k + 50),
}))

/* ---------------- ReadNext ---------------- */
const RN_KIND = { D: 'Docs', B: 'Blog', V: 'Video', E: 'Ecosystem', P: 'Product', G: 'Guide', C: 'Case study', R: 'Research', I: 'Dive', W: 'Webinar', O: 'Podcast' }
function readNextOf(spec, seed) {
  return (spec || '').split(' ').filter(Boolean).map((tok, k) => {
    const m = tok.match(/^([A-Z])([0-9a-z]+)(?::(.*))?$/)
    const [, c, w, path] = m
    const r = rng(seed * 5 + k)
    const href = path || {
      D: '/docs/getting-started', B: `/blog/sample-post-${int(r, 1, 272)}`, V: `/videos/sample-video-${int(r, 1, 159)}`,
      E: `/ecosystem/partner-${int(r, 1, 40)}`, C: `/case-studies/case-study-${int(r, 1, 20)}`,
    }[c] || '/blog'
    return { kind: RN_KIND[c], title: fromShape(w, seed * 3 + k), href, gated: c === 'P' || c === 'G', cta: c === 'G' ? 'Get the guide' : 'Explore the product', seed: seed + k }
  })
}

const glossHref = (seed) => `/glossary/${GLOSSARY_SLUGS[seed % GLOSSARY_SLUGS.length]}`
const learnHref = (seed) => `/learn/${LEARN_SLUGS[seed % LEARN_SLUGS.length]}`
const mixedHref = (seed) => [glossHref, learnHref, (x) => `/blog/sample-post-${(x % 272) + 1}`, () => '/docs/getting-started'][seed % 4](seed)

/* ---------------- X1 / X2 glossary ---------------- */
const ALIASES = { dlt: 'data-load-tool-dlt', 'time-series-database': 'time-series' }
export const glossaryTerms = lazy(() => GLOSSARY_SLUGS.map((slug, i) => {
  const row = G_ROWS[i]
  const L = /^[a-z]/.test(slug) ? slug[0].toUpperCase() : '#'
  return { i, slug, term: titleFromSlug(slug), letter: L, summary: chars(row[0] || 160, hash(slug) % 100000) }
}))
// The original's term body carries one promo card (aside: eyebrow p, H3 title, p, CTA button), flattened in the measured
// shape as `p.<=18|h3.N|p.M`. It is lifted out of the prose here: { at: block index it precedes, eyebrow, title, text, cta, href }.
const PROMO_TO = { 15: '/duckdb-cheatsheet-full', 17: '/duckdb-book-brief' }
function splitPromo(shape, seed) {
  const toks = String(shape || '').split('|')
  const k = toks.findIndex((t, j) => t.startsWith('h3.') && /^p\.(\d+)$/.test(toks[j - 1] || '') && Number(toks[j - 1].slice(2)) <= 18 && /^p\.\d+$/.test(toks[j + 1] || ''))
  if (k < 1) return { shape, promo: null }
  const eye = Number(toks[k - 1].slice(2))
  const promo = {
    before: toks.slice(0, k - 1).join('|'),
    eyebrow: exactTitle(eye, seed + 501),
    title: exactTitle(Number(toks[k].slice(3)), seed + 502),
    text: chars(Number(toks[k + 1].slice(2)), seed + 503),
    cta: eye === 17 ? 'Get the book' : 'Download the guide',
    href: PROMO_TO[eye] || '/lp/ducklake-lakehouse-table-format-book',
  }
  return { shape: [...toks.slice(0, k - 1), ...toks.slice(k + 2)].join('|'), promo }
}
export function getTerm(slug) {
  const key = String(slug || '').toLowerCase()
  const canon = ALIASES[key] || key
  const all = glossaryTerms()
  let t = all.find((x) => x.slug === canon)
  if (!t) t = { i: hash(key) % all.length, slug: key, term: titleFromSlug(key), letter: key[0]?.toUpperCase() || '#', summary: chars(180, hash(key) % 100000), unknown: true }
  const row = G_ROWS[t.i]
  const seed = (hash(t.slug) % 9000) + 1
  const { shape, promo } = splitPromo(row[1], seed)
  const related = nums(row[4]).map((k) => all[k]).filter(Boolean)
  while (related.length < 6) related.push(all[(t.i + related.length * 37 + 11) % all.length])
  return {
    ...t,
    updated: 'July 2026',
    body: t.unknown ? decodeShape('p.700.2|p.44.1', { seed, hrefFor: mixedHref }) : decodeShape(shape, { seed, hrefFor: mixedHref }),
    promo: t.unknown || !promo ? null : { ...promo, at: decodeShape(promo.before, { seed, hrefFor: mixedHref }).length },
    related: related.slice(0, nums(row[4]).length || 6),
    faqs: faqsOf(row[2], row[3], seed),
    readNext: readNextOf(row[5] || 'B44 D32 V60', seed),
  }
}
export const GLOSSARY_LEDE = [chars(78, 9101).replace(/\.$/, ','), chars(66, 9102)]

/* ---------------- X5 dives ---------------- */
// diveTitle: shared with the dive-gallery cards (content/slugNames.js).
function promptText(spec, seed) {
  const [n, lines] = spec.split(':').map(Number)
  const words = chars(n, seed).split(' ')
  const per = Math.ceil(words.length / Math.max(1, lines))
  return Array.from({ length: lines }, (_, i) => words.slice(i * per, (i + 1) * per).join(' ')).filter(Boolean).join('\n')
}
export function getDive(slug) {
  const key = String(slug || '').toLowerCase()
  let i = DIVE_SLUGS.indexOf(key)
  const known = i >= 0
  if (!known) i = hash(key) % DIVE_SLUGS.length
  const row = D_ROWS[i]
  const seed = (hash(key) % 9000) + 1
  const handleLen = Math.max(5, row[2] || 7)
  const num = String(seed)
  return {
    slug: key,
    seed,
    title: diveTitle(key),
    description: chars(row[0] || 300, seed + 3),
    tags: row[1] ? row[1].split(',') : ['Explorer'],
    author: ('user' + num).slice(0, handleLen).padEnd(handleLen, '0'),
    date: row[3] || 'June 20, 2026',
    region: row[4] || 'us-east-1',
    votes: row[5] ?? 0,
    prompts: (row[6] || '').split(' ').filter(Boolean).map((p, k) => promptText(p, seed * 10 + k)),
    comments: [],
  }
}

/* ---------------- X6 authors ---------------- */
export function authorName(slugOrIdx) {
  const i = typeof slugOrIdx === 'number' ? slugOrIdx : AUTHOR_SLUGS.indexOf(slugOrIdx)
  const k = i >= 0 ? i : hash(String(slugOrIdx)) % AUTHOR_SLUGS.length
  return nameOfLength(A_ROWS[k][0] || 12, k * 17 + 3)
}
// The original lists at most 36 cards; its heading counts every post and video. Totals measured where they exceed 36
// (all other authors: heading = card count).
const A_TOTAL = { 'jacob-matson': 61, 'mehdi-ouazza': 104, 'simon-spati': 47 }
export function getAuthor(slug, videoPool = []) {
  const key = String(slug || '').toLowerCase()
  let i = AUTHOR_SLUGS.indexOf(key)
  if (i < 0) i = hash(key) % AUTHOR_SLUGS.length
  const [nameLen, roleLen, bioLen, itemSpec] = A_ROWS[i]
  const name = authorName(i)
  const seed = (hash(key) % 9000) + 1
  const items = (itemSpec || '').split(' ').filter(Boolean).map((tok, k) => {
    const lens = nums(tok.slice(1))
    const r = rng(seed * 31 + k)
    if (tok[0] === 'p') {
      const date = dateFor(seed * 7 + k)
      // byline length as measured (co-authored posts run to 40+ chars and wrap to 2 lines)
      let byline = `${date} · ${name}`
      const extra = (lens[1] || 0) - byline.length - 2
      if (extra >= 9) byline += `, ${nameOfLength(Math.min(extra, 20), seed * 3 + k)}`
      return { kind: 'post', to: `/blog/sample-post-${int(r, 1, 272)}`, title: exactTitle(lens[0] || 50, seed * 9 + k), byline, excerpt: chars(lens[2] || 280, seed * 11 + k) }
    }
    const base = videoPool.length ? videoPool[int(r, 0, videoPool.length - 1)] : { slug: `sample-video-${k + 1}`, duration: '0:45:10', date: dateFor(seed + k), tags: ['Talk'] }
    const desc = Math.max(...lens, 120)
    return { kind: 'video', v: { ...base, title: exactTitle(int(r, 30, 70), seed * 13 + k), desc: chars(desc, seed * 15 + k) } }
  })
  return { slug: key, name, nameLen, role: roleOfLength(roleLen || 14), bio: chars(bioLen || 150, seed + 1), social: Number(A_SOCIAL[i] || 0), items, total: A_TOTAL[AUTHOR_SLUGS[i]] || items.length, seed }
}

/* ---------------- X7 learn ---------------- */
const LEARN_ICONS = ['lRing', 'lBolt', 'lGrid', 'lPurple', 'lChartDrum', 'lCloudTerm', 'lPipFolders', 'lLinked', 'lDrums', 'lBookDrum']
export function getLearn(slug) {
  const key = String(slug || '')
  let i = LEARN_SLUGS.findIndex((s) => s.toLowerCase() === key.toLowerCase())
  if (i < 0) i = hash(key) % LEARN_SLUGS.length
  const [h1, readMin, updated, authorIdx, shape, fq, fa, rn] = L_ROWS[i]
  const seed = (hash(LEARN_SLUGS[i]) % 9000) + 7
  const body = decodeShape(shape, { seed, hrefFor: mixedHref, imgRatio: 0.5895 })
  return {
    slug: key,
    title: fromShape(h1, seed, 60),
    readMin,
    updated,
    authors: nums(authorIdx).map((k) => ({ slug: AUTHOR_SLUGS[k], name: authorName(k) })),
    icon: LEARN_ICONS[i % LEARN_ICONS.length],
    body,
    faqs: faqsOf(fq, fa, seed),
    readNext: readNextOf(rn || 'B40 D30 V50', seed),
  }
}

/* ---------------- X11 research ---------------- */
export function getPaper(slug) {
  const key = String(slug || '').toLowerCase()
  let i = RESEARCH_SLUGS.indexOf(key)
  if (i < 0) i = hash(key) % RESEARCH_SLUGS.length
  const [h1, byLen, shape] = R_ROWS[i]
  const seed = (hash(RESEARCH_SLUGS[i]) % 9000) + 11
  const names = []
  let len = 0
  for (let k = 0; len < (byLen || 16) - 2; k++) {
    const nm = nameOfLength(int(rng(seed + k), 9, 15), seed * 3 + k)
    names.push(nm)
    len += nm.length + 2
  }
  return {
    slug: key,
    title: fromShape(h1, seed),
    date: dateFor(seed),
    authors: names.join(', '),
    body: decodeShape(shape, { seed, hrefFor: mixedHref, imgRatio: 0.56 }),
  }
}

/* ---------------- X20 book chapter summaries ---------------- */
export function getChapter(n) {
  const row = C_ROWS[(n - 1 + 11) % 11]
  const [h1, readMin, shape, fq, fa] = row
  const seed = n * 101 + 5
  return {
    n,
    title: fromShape(h1, seed),
    readMin,
    cta: { before: chars(48, seed + 1).replace(/\.$/, ''), book: exactTitle(16, seed + 2), link: 'Download the complete book' },
    body: decodeShape(shape, { seed, hrefFor: (x) => (x % 3 === 0 ? learnHref(x) : glossHref(x)), imgRatio: 0.5625, numbered: n }),
    faqs: faqsOf(fq, fa, seed),
  }
}

